SELECT , m.Nombre AS medicoNombre, m.Apellidos AS medicoApellidos
  FROM guardias_medicos g
  LEFT JOIN medicos m ON m.ID = g.IdMedico
 WHERE g.IdServicio = #{servicioId}
   AND LEFT(g.FGuardia, 10) BETWEEN #{desde} AND #{hasta}
 ORDER BY LEFT(g.FGuardia, 10), g.Id

SELECT , NULL AS medicoNombre, NULL AS medicoApellidos
  FROM guardias_medicos g
 WHERE g.IdMedico = #{medicoId}
   AND LEFT(g.FGuardia, 10) = #{fecha}
   AND g.IdServicio = #{servicioId}
 ORDER BY g.Id

SELECT , NULL AS medicoNombre, NULL AS medicoApellidos
  FROM guardias_medicos g
 WHERE g.IdServicio = #{servicioId}
   AND LEFT(g.FGuardia, 10) = #{fecha}
 ORDER BY g.Id
